 * A CliError carries the exit code the process should use alongside the
 * single line that should be written to standard error.
 */
export class CliError extends Error {
  constructor(exitCode, message) {
    super(message)
    this.exitCode = exitCode
  }
}

export function usageError() {
  return new CliError(2, 'error: usage: cli.js waves|explain|pack <workers>')
}

export function workersError() {
  return new CliError(2, 'error: workers must be a positive integer')
}

export function lineError(line, message) {
  return new CliError(2, `error: line ${line}: ${message}`)
}

export function unknownTaskError(name) {
  return new CliError(2, `error: unknown task ${name}`)
}

export function cycleError(names) {
  return new CliError(3, `error: cycle: ${names.join(' -> ')}`)
}
"}

