{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-bjChCb/src/parse.js","content":"import { lineError, unknownTaskError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the raw build-graph text into a graph description:
 *   { tasks: Map<name, cost>, deps: Map<name, Set<name>> }
 * Throws a CliError for any malformed input, per the specification.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map()
  const deps = new Map()
  const depUsages = [] // ordered list of names used by dep lines, in input order

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw lineError(lineNo, 'expected task <name> <cost>')
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw lineError(lineNo, `invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw lineError(lineNo, 'cost must be a non-negative integer')
      }
      if (tasks.has(name)) {
        throw lineError(lineNo, `task ${name} is declared twice`)
      }
      const cost = parseInt(costStr, 10)
      tasks.set(name, cost)
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw lineError(lineNo, 'expected dep <name> <dependency>...')
      }
      const [, name, ...rest] = words
      depUsages.push(name)
      for (const dep of rest) depUsages.push(dep)
      if (!deps.has(name)) deps.set(name, new Set())
      for (const dep of rest) {
        deps.get(name).add(dep)
      }
    } else {
      throw lineError(lineNo, `unknown directive ${directive}`)
    }
  }

  for (const name of depUsages) {
    if (!tasks.has(name)) {
      throw unknownTaskError(name)
    }
  }

  return { tasks, deps }
}
"}

