{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-bjChCb/src/graph.js","content":"import { cycleError } from './errors.js'

/**
 * Finds the first cycle a depth-first search discovers when it starts from
 * each task in ascending name order and walks each task's dependencies in
 * ascending name order. Returns an array of names from the re-entered task
 * through the search stack back to itself (with the name repeated at the
 * end), or null if the graph is acyclic.
 */
function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map() // undefined = unvisited, 'visiting', 'done'
  let cyclePath = null

  function dfs(node, stack) {
    state.set(node, 'visiting')
    stack.push(node)
    const neighbours = [...deps.get(node)].sort()
    for (const next of neighbours) {
      if (cyclePath) return
      const st = state.get(next)
      if (st === 'visiting') {
        const idx = stack.indexOf(next)
        cyclePath = stack.slice(idx).concat(next)
        return
      } else if (st !== 'done') {
        dfs(next, stack)
        if (cyclePath) return
      }
    }
    if (cyclePath) return
    stack.pop()
    state.set(node, 'done')
  }

  for (const name of names) {
    if (cyclePath) break
    if (state.get(name) !== 'done') {
      dfs(name, [])
    }
  }

  return cyclePath
}

/** Throws a CliError if the graph has a cycle. */
export function checkAcyclic(tasks, deps) {
  const cycle = findCycle(tasks, deps)
  if (cycle) throw cycleError(cycle)
}

/**
 * Computes, for every task: depth (wave index), start and finish, assuming
 * unlimited workers. Returns Maps keyed by task name.
 */
export function computeTimings(tasks, deps) {
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const depList = deps.get(name)
    if (depList.size === 0) {
      depth.set(name, 0)
      start.set(name, 0)
    } else {
      let maxDepth = -1
      let maxFinish = 0
      for (const dep of depList) {
        compute(dep)
        if (depth.get(dep) > maxDepth) maxDepth = depth.get(dep)
        if (finish.get(dep) > maxFinish) maxFinish = finish.get(dep)
      }
      depth.set(name, maxDepth + 1)
      start.set(name, maxFinish)
    }
    finish.set(name, start.get(name) + tasks.get(name))
  }

  for (const name of tasks.keys()) compute(name)

  return { depth, start, finish }
}

/** The makespan with unlimited workers: the greatest finish, or 0. */
export function totalTime(finish) {
  let max = 0
  for (const f of finish.values()) {
    if (f > max) max = f
  }
  return max
}

/**
 * Computes the priority of every task: the cost of the longest chain that
 * begins at it and runs forward through its dependents down to a task
 * nothing depends on.
 */
function computePriorities(tasks, deps) {
  const dependentsOf = new Map()
  for (const name of tasks.keys()) dependentsOf.set(name, [])
  for (const [name, depSet] of deps) {
    for (const dep of depSet) {
      dependentsOf.get(dep).push(name)
    }
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dependent of dependentsOf.get(name)) {
      const p = compute(dependent)
      if (p > best) best = p
    }
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulates the build graph on the given number of workers and returns
 * { runs: Array<Array<{name, start, finish}>>, makespan }.
 */
export function pack(tasks, deps, workerCount) {
  const names = [...tasks.keys()].sort()
  const total = names.length
  const priority = computePriorities(tasks, deps)

  const workerFree = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])
  const finished = new Map()
  const started = new Set()

  let time = 0
  while (started.size < total) {
    let progress = true
    while (progress) {
      progress = false

      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFree[i] <= time) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let bestTask = null
      let bestPriority = -1
      for (const name of names) {
        if (started.has(name)) continue
        const depSet = deps.get(name)
        let ready = true
        for (const dep of depSet) {
          const f = finished.get(dep)
          if (f === undefined || f > time) {
            ready = false
            break
          }
        }
        if (!ready) continue
        const p = priority.get(name)
        if (p > bestPriority) {
          bestPriority = p
          bestTask = name
        }
      }
      if (bestTask === null) break

      const cost = tasks.get(bestTask)
      const start = time
      const fin = time + cost
      workerFree[freeWorker] = fin
      runs[freeWorker].push({ name: bestTask, start, finish: fin })
      started.add(bestTask)
      finished.set(bestTask, fin)
      progress = true
    }

    if (started.size < total) {
      let next = Infinity
      for (let i = 0; i < workerCount; i++) {
        if (workerFree[i] > time && workerFree[i] < next) next = workerFree[i]
      }
      time = next
    }
  }

  let makespan = 0
  for (const f of finished.values()) {
    if (f > makespan) makespan = f
  }

  return { runs, makespan }
}
"}

