/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import fs from 'node:fs'
import { CliError, usageError, workersError } from './errors.js'
import { parseGraph } from './parse.js'
import { checkAcyclic, computeTimings, totalTime, pack } from './graph.js'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    const workersStr = argv[1]
    if (!/^[1-9][0-9]*$/.test(workersStr)) {
      throw workersError()
    }
    return { mode: 'pack', workers: parseInt(workersStr, 10) }
  }
  throw usageError()
}

function formatWaves(tasks, depth, finish) {
  const byDepth = new Map()
  for (const [name, d] of depth) {
    if (!byDepth.has(d)) byDepth.set(d, [])
    byDepth.get(d).push(name)
  }
  const maxDepth = byDepth.size === 0 ? -1 : Math.max(...byDepth.keys())

  const lines = []
  for (let k = 0; k <= maxDepth; k++) {
    const names = (byDepth.get(k) || []).sort()
    lines.push(`wave ${k}: ${names.join(' ')}`)
  }
  lines.push(`total ${totalTime(finish)}`)
  return lines.join('\n') + '\n'
}

function formatExplain(tasks, depth, start, finish) {
  const names = [...tasks.keys()].sort()
  const lines = []
  for (const name of names) {
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  }
  lines.push(`total ${totalTime(finish)}`)
  return lines.join('\n') + '\n'
}

function formatPack(runs, makespan) {
  const lines = []
  for (let i = 0; i < runs.length; i++) {
    const parts = runs[i].map((r) => `${r.name}@${r.start}-${r.finish}`)
    if (parts.length === 0) {
      lines.push(`worker ${i}:`)
    } else {
      lines.push(`worker ${i}: ${parts.join(' ')}`)
    }
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = fs.readFileSync(0, 'utf8')
  const { tasks, deps } = parseGraph(input)
  checkAcyclic(tasks, deps)

  if (args.mode === 'waves') {
    const { depth, finish } = computeTimings(tasks, deps)
    process.stdout.write(formatWaves(tasks, depth, finish))
  } else if (args.mode === 'explain') {
    const { depth, start, finish } = computeTimings(tasks, deps)
    process.stdout.write(formatExplain(tasks, depth, start, finish))
  } else if (args.mode === 'pack') {
    const { runs, makespan } = pack(tasks, deps, args.workers)
    process.stdout.write(formatPack(runs, makespan))
  }
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.exitCode)
  }
  throw err
}
"}

